# name: sequential_yes_dependence
# description: P(yes | previous trial yes) minus P(yes | previous trial no) over consecutive trials (trial_index step of 1); observed above null means response perseveration / carry-over that the trial-independent model does not produce.
def test_statistic(df):
    ti = df["trial_index"].astype(int).to_numpy()
    r = df["rating"].astype(float).to_numpy()
    ok = np.diff(ti) == 1
    prev, cur = r[:-1][ok], r[1:][ok]
    if (prev == 1).sum() == 0 or (prev == 0).sum() == 0:
        return 0.0
    return float(cur[prev == 1].mean() - cur[prev == 0].mean())

# name: four_vs_two_example_yes_gap
# description: Yes-rate on 4-example sets minus yes-rate on 2-example sets; observed more negative than null means people tighten generalization with more examples more than the model does, more positive means less.
def test_statistic(df):
    n = df["number_set"].astype(str).str.count(",").to_numpy() + 1
    r = df["rating"].astype(float).to_numpy()
    a, b = r[n == 4], r[n == 2]
    if len(a) == 0 or len(b) == 0:
        return 0.0
    return float(a.mean() - b.mean())

# name: trial_index_slope
# description: Correlation between trial_index and yes response; nonzero observed vs a ~0 null means the yes-rate drifts over the session (fatigue/learning), which the stationary model cannot produce (sign gives drift direction).
def test_statistic(df):
    x = df["trial_index"].astype(float).to_numpy()
    y = df["rating"].astype(float).to_numpy()
    if x.std() == 0 or y.std() == 0:
        return 0.0
    return float(np.corrcoef(x, y)[0, 1])
